insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place)
values
(E'https://matcha-jp.com/en/7820', E'en', 39, E'KITKAT x Yuzu Liqueur! Delicious Bijofu Sake From Kochi Meets Chocolate', E'KITKAT Mini Yuzu-shu Bijofu is the newest addition to the KITKAT Sake series after KITKAT Mini Japanese Sake Masuizumi and KITKAT Mini Umeshu Tsuru-Ume.This chocolate is made in cooperation with Kochi prefecture, famous for its yuzu production, and Bijofu breweries excellent yuzu liqueur\n\nNestlé Japan offers the widest variety of KITKAT-flavors in the world. With seasonal as well as monthly product releases, KITKAT chocolates are some of the most popular souvenirs from Japan.\n\nTwo years ago, KITKAT introduced their Japanese sake series to introduce the delicious flavor of Japanese sake and liquor to the world through KITKAT chocolate. After releasing the KITKAT Japanese SAKE in 2017 and the KITKAT Umeshu (plum wine) in 2018, they are releasing a KITKAT Yuzu-shu Bijofu with real yuzu infused sake 2019. To create this new product, KITKAT teamed up with breweries from Kochi, a region that is famous for its production of yuzu (Asian citrus fruit).\n\nThe former name of Kochi Prefecture is Tosa. Tosa and its famous samurai Sakamoto Ryoma played an important historical role in ending the reign of feudal lords in Japan. One of the most famous sites in Kochi is Kochi Castle.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/02-85062.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/25-84579.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/25-84580.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/03-85114.webp"]'::jsonb, E'2019-08-22'::timestamptz, E'Tosa'),
(E'https://matcha-jp.com/en/4186', E'en', 39, E'Kochi Castle - An Elegant Castle From The Edo Period', E'Kochi Castle, located in Kochi prefecture, a part of the Shikoku Region, is known for its precious architecture dating back to the Edo Period.\n\nKochi Castle is located in Kochi City, Kochi prefecture, in the Shikoku Region. The castle was built by Yamauchi Kazutoyo, who ruled the Kochi area about 400 years ago. The castle, famous for its elegant tenshu (*1), the massive walls and gates, is known as the "best castle in the Nankaido (*2)". It is also precious as the tenshu and honmaru goten (*3), built in the Edo Period, still remain, and it has been chosen as one of Japan\'s Top 100 Castles.\n\nThe original tenshu, built by Yamauchi Kazutoyo, was lost to the fire in 1727. The tenshu was rebuilt according to the original plan in 1749. Since then, the castle has survived natural disasters, the Ordinance for the Disposal of Castles (*4) issued by the Meiji Government and World War II. Due to that history, the castle is also known as a "Castle of Fortune".\n\nThis article is about the Kochi Castle, a landmark of the Shikoku Region, and its highlights.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/17-21572.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/17-21557.webp"]'::jsonb, E'2017-05-09'::timestamptz, null),
(E'https://matcha-jp.com/en/1354', E'en', 40, E'Fukuoka in Autumn 2026: Top 10 Fall Foliage Destinations', E'Discover 10 famous autumn foliage spots around Fukuoka: the beautiful Rakusuien Garden, Maizuru Park, the Akizuki Castle Ruins, Kokura Castle, and more.\n\nFor reference: 2025 fall foliage map based on information from Weathernews. The 2026 forecast is yet to be announced.\n\nLocated in northern Kyushu, Fukuoka is famous for its beautiful nature, friendly people, and a variety of delicious cuisine.\n\nThe autumn foliage in Fukuoka can be enjoyed from early November to late November (it can last up to early December, depending on location). Be aware that the season may vary slightly depending on the yearly climate and location.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/10/07-246219.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/18-241500.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/04-195374.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/17-58553.webp"]'::jsonb, E'2018-12-17'::timestamptz, E'Fukuoka'),
(E'https://matcha-jp.com/en/2624', E'en', 40, E'Fukuoka City: 25 Things to Do, Day Trips, Dining, and More', E'Fukuoka, the largest city in Kyushu, is a popular travel destination for its historical shrines and festivals, excellent food, as well as excellent shopping spots and entertainment. We introduce 25 things to do and must-visit places, as well as local eats to try in the central Hakata area.\n\nFukuoka is the largest prefecture in the Kyushu region. Fukuoka City, the capital and center of the prefecture, is a metropolis operating as the travel hub of Kyushu.\n\nThe city is divided to the west and east of Naka River and is respectively known as “Fukuoka” and “Hakata.” In recent years, the city’s entertainment facilities were enriched with the opening of Marine World Uminonakamichi and Gundam Park Fukuoka.\n\nFukuoka is accessible in two hours by plane and about five hours by bullet train from Tokyo. The city center is quite close to the airport, so the area has great accessibility.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/08/23-193732.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/29-46857.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/30-133408.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/10-122517.webp"]'::jsonb, E'2018-12-17'::timestamptz, E'Fukuoka'),
(E'https://matcha-jp.com/en/3711', E'en', 40, E'10 Popular Fukuoka Souvenirs You Can Get At The Airport!', E'Fukuoka is one of the most exciting travel destinations in Kyushu. Check out our selection of recommended souvenirs specific to Fukuoka, which are great to take home to your dear ones and also as a reminder of your trip!\n\nIf you’re planning to bring home souvenirs from Fukuoka (Hakata), mentaiko (seasoned cod roe) is definitely the most popular local specialty. However, it needs to be refrigerated, so you might be worrying a bit about its freshness after a long flight. This article takes a look at the best souvenirs for international tourists, mainly from Fukuoka, which are easy to purchase and easy to take home.\n\nWe’ll check out snacks featuring mentaiko, Hakata’s long-famous confectioneries, and more. If you’re having trouble choosing souvenirs, refer to this article and you can’t go wrong!\n\nMentaiko is a staple souvenir from Fukuoka. While it’s delicious in and of itself, mentaiko is also a popular snack flavor, and you can find many mentaiko-flavored local snacks in Fukuoka.', E'["https://resources.matcha-jp.com/resize/720x2000/2016/12/08-11266.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/08-11267.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/08-11268.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/08-11269.webp"]'::jsonb, E'2018-12-17'::timestamptz, E'Fukuoka'),
(E'https://matcha-jp.com/en/1545', E'en', 40, E'Kyushu Region - Japanese Encyclopedia', E'Kyushu is the southwesternmost region of Japan and consists of seven prefectures. The largest city in Kyushu is Fukuoka. Fukuoka Airport is very convenient for flying to international and domestic destinations.\n\nKyushu is a region that consisted of nine provinces in the past, that is why its name translates to "the nine provinces". Kyushu is one of Japan\'s four large islands and is located in the southwestern part of the country.\n\nThe Kyushu Region presently consists of seven prefectures: Fukuoka, Saga, Nagasaki, Kumamoto, Oita, Miyazaki, and Kagoshima. Kyushu\'s largest city, Fukuoka, is home to a population of 1.46 million people (as of January 2016).\n\nFukuoka Airport is a major air transportation hub for international and domestic flights. It is served by a subway line that can be used to reach Hakata Station, a major stop on the Shinkansen line. This airport is very convenient for reaching Fukuoka and all the cities in Kyushu, as well as international and domestic destinations.', E'["https://resources.matcha-jp.com/archive_files/jp/2016/01/kyushu.webp","https://resources.matcha-jp.com/resize/720x2000/2020/07/07-104748.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/19-126809.webp","https://resources.matcha-jp.com/resize/720x2000/2020/07/07-104744.webp"]'::jsonb, E'2016-03-02'::timestamptz, E'Fukuoka'),
(E'https://matcha-jp.com/en/7306', E'en', 41, E'Saga Travel Guide – Scenic Spots, Food, And Fun Things To Do', E'Saga is full of things to do and see, from an international hot air balloon festival and rice terraces to shopping. The prefecture is also renowned for its local food, like wagyu beef and seafood. Read to learn what to put on your trip itinerary to Saga.\n\nSaga Prefecture is filled with one-of-a-kind activities and destinations, such as a hot air balloon festival, torii gates that appear to be floating on water, and terraced rice fields. Visitors can keep up with the latest trends at a shopping outlet and a stylish library. Delicious food, including fresh seafood and wagyu beef, is also a must-try in Saga.\n\nAll of these things can be encountered in Saga on Japan\'s southern island of Kyushu. Continue reading this complete guide to Saga to find what you can do and see in this prefecture.\n\nSaga Prefecture is in northern Kyushu, east of Fukuoka, and west of Nagasaki, which is known for Huis Ten Bosch and its charming towns. The yellow pin is Kyushu Saga International Airport.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75929.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75911.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/17-75371.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/17-75372.webp"]'::jsonb, E'2019-06-02'::timestamptz, E'Saga'),
(E'https://matcha-jp.com/en/4163', E'en', 42, E'Nagasaki Kunchi Festival 2026: Dates, Access, and Highlights', E'Discover Nagasaki Kunchi, October 7-9. Explore highlights, venues and tips for this historic fall festival, a National Important Intangible Folk Cultural Asset.\n\nNagasaki Kunchi is a fall festival annually held at Suwa Shrine in Nagasaki from October 7 to October 9. The event has been designated as a National Important Intangible Folk Cultural Asset.\n\n“Kunchi” is a word from the northern Kyushu dialect meaning autumn festival. Nagasaki Kunchi along with Hakata O-Kunchi in Fukuoka and Karatsu Kunchi in Saga are known as Japan’s Top Three Kunchi.\n\nThe origins of the Nagasaki Kunchi Festival can be traced to about 400 years ago. The festival originated from an event when two female dancers performed a dance program called “Komee” at Suwa Shrine.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/06/16-139570.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/16-139571.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/14-21260.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/14-21261.webp"]'::jsonb, E'2017-04-16'::timestamptz, E'Nagasaki'),
(E'https://matcha-jp.com/en/2058', E'en', 42, E'From Tokyo to Nagasaki: Travel Time, Fares, Discount Passes', E'Find the fastest and cheapest ways to travel from Tokyo to Nagasaki. Compare flights, Shinkansen bullet trains, and regional travel passes to save money.\n\nTraveling from Tokyo to Nagasaki spans a distance of roughly 1,300 km (over 800 miles), taking you from the capital down to the western coast of Kyushu.\n\nThe two primary ways to travel this route are by air (the fastest and often cheapest if booked early) and Shinkansen (bullet train), which is the scenic, seamless, and luggage-friendly option.\n\nTable of Contents From Tokyo to Nagasaki: Comparison Table of Travel Methods 1. By Air (Recommended): Choose from Budget and Full-Service Flights 2. By Shinkansen: With Transfer at Hakata Station 3. Fly to Fukuoka, Then Travel by Train or Bus to Nagasaki Book Shinkasen and train tickets in Japan Book the JR Pass for Whole Japan Book the JR Kyushu Rail Pass From Tokyo to Nagasaki: Comparison Table of Travel Methods Mode of Transport Total Travel Time One-Way Fare Range Best For Flying from Haneda Airport 3.5 to 4 hours (2h flight + city transfers) 15,000 - 35,000 yen Speed, convenience, and direct airport access from central Tokyo Flying (LCC / Budget) from Narita Airport 4.5 to 5 hours (2h 10m flight + city transfers) 8,000 - 18,000 yen Budget travelers Shinkansen (Bullet Train) 7 to 7.5 hours (Requires 2 transfers) 29,220 yen Travelers with heavy luggage, JR Pass holders 1. By Air (Recommended): Choose from Budget and Full-Service Flights Nagasaki Airport. Photo by Pixta', E'["https://resources.matcha-jp.com/resize/720x2000/2026/06/25-266020.webp","https://resources.matcha-jp.com/resize/720x2000/2026/06/25-266019.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/1637.webp","https://resources.matcha-jp.com/resize/720x2000/2023/08/24-144009.webp"]'::jsonb, E'2016-07-29'::timestamptz, E'Nagasaki'),
(E'https://matcha-jp.com/en/11328', E'en', 42, E'Nagasaki Day Trip to Iojima Island: 5 Scenic Places to Visit', E'Discover 5 beautiful places to visit on Iojima, a scenic Nagasaki resort island just 30 mins away from the city. Explore historic spots, cafes, hot springs, and ocean views!\n\nIojima Island, also known as Oki-no-shima among locals, is a tranquil resort paradise accessible from Nagasaki City by both a 20-minute ferry and a mainland bridge.\n\nOnce a prosperous coal-mining town, the island has reinvented itself as a premier leisure destination.\n\nToday, it is home to i+Land nagasaki, an expansive entertainment resort featuring luxury accommodations, natural hot spring spas, and the Costa del Sol swimming beach.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/06/01-264936.webp","https://resources.matcha-jp.com/resize/720x2000/2022/08/31-129393.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/01-129398.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/01-129399.webp"]'::jsonb, E'2026-05-15'::timestamptz, E'Nagasaki'),
(E'https://matcha-jp.com/en/4350', E'en', 43, E'Kurokawa Onsen: Best Hot Spring Inns, Access, and Travel Tips', E'Located on the picturesque Mt. Aso in Kumamoto, Kurokawa Onsen offers stunning natural scenery, charming town views, and exceptional outdoor hot springs. Read on to learn how to get to Kurokawa Onsen, the best hotels and inns, and recommended activities.\n\n\'Taki no yu\' from Ikoi Ryokan (Photo courtesy of: Kurokawa Onsen Ryokan Association)\n\nLocated in the heart of the Kyushu region, Kurokawa Onsen is a historic hot spring with over 300 years of tradition, situated in Kumamoto Prefecture.\n\nEach ryokan, or Japanese-style inn, features unique outdoor hot springs that offer breathtaking views of the surrounding mountains and flowing streams. This area is particularly special because it boasts six different types of hot springs, with the water color changing depending on the spring and the time of day.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/04/21-24930.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/21-24931.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/21-24932.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/1637.webp"]'::jsonb, E'2017-10-15'::timestamptz, E'Kurokawa Onsen'),
(E'https://matcha-jp.com/en/20733', E'en', 43, E'Amakusa: 5 Amazing Places to Visit and a 2-Day Suggested Itinerary', E'Amakusa, a beautiful island city in Kumamoto, is a great place for those who love nature, history, and seaside activities like dolphin watching. We\'ll introduce places to visit, dining facilities, and hotels. You\'ll also find a two-day suggested itinerary for exploring the area!\n\nAmakusa is a city spreading over several islands in Kumamoto. This article provides a detailed introduction to Amakusa\'s tourist attractions, including dolphin watching, gourmet spots serving fresh seafood, and historic villages.\n\nMoreover, we will introduce a 2-day suggested itinerary to fully enjoy the charm and history of Amakusa, along with recommended hotels.\n\nAmakusa is located in the southwestern part of Kumamoto Prefecture and comprises approximately 120 islands.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189751.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189750.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189752.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189753.webp"]'::jsonb, E'2024-10-15'::timestamptz, E'Amakusa'),
(E'https://matcha-jp.com/en/21434', E'en', 40, E'How to Travel from Fukuoka to Kumamoto: By Shinkansen, Train, and Bus', E'Kumamoto\'s popularity as a travel destination has surged in recent years, making transportation between Fukuoka and Kumamoto crucial. This article explores convenient travel options, from the Kyushu Shinkansen to highway buses and trains, to help you choose the best way to reach Kumamoto.\n\nTraveling from Fukuoka to Kumamoto is quite convenient and simple. The main transportation options include the Kyushu Shinkansen, train, and highway bus.\n\nEach mode of transport has advantages and disadvantages. We compare them below so you can choose the route based on your itinerary.\n\nThe fastest train category along the Kyushu Shinkansen is the Mizuho, which takes about 32 minutes to reach Kumamoto. The next stop after Hakata Station is Kumamoto Station, although some trains may stop at Kurume Station.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/01/26-121632.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/06-196019.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/06-195939.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/06-195948.webp"]'::jsonb, E'2024-09-25'::timestamptz, E'Fukuoka'),
(E'https://matcha-jp.com/en/10212', E'en', 44, E'Southern Oita Travel: 20 Things to Do, Scenic Views, Cuisine', E'Beyond Beppu and Yufuin, explore southern Oita! Discover 20 must-visit spots in Usuki, Saiki, Tsukumi, and Bungo-Ono, from historic sites to coastal geoparks.\n\nOita, with its famous hot spring resorts such as Beppu Onsen and Yufuin, is often called "the hot-spring prefecture."\n\nHowever, southern Oita boasts stunning views of the ocean and the mountains, World Heritage sites, and exquisite local food. n this article, we introduce 20 excellent places to visit in cities such as Usuki, Saiki, Tsukumi, and Bungo-Ono, all located in southern Oita.\n\nIn the sixteenth century, Usuki was an international port visited by Portuguese and Chinese merchants. The streets are lined with buildings from various eras, and visitors can enjoy a different side of the city\'s history at every corner.', E'["https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110689.webp","https://resources.matcha-jp.com/resize/720x2000/2020/10/28-108692.webp","https://resources.matcha-jp.com/resize/720x2000/2020/10/28-108689.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110690.webp"]'::jsonb, E'2020-10-27'::timestamptz, E'Beppu Onsen'),
(E'https://matcha-jp.com/en/2031', E'en', 45, E'Udo-jingū, Miyazaki - Test Your Luck At This Cavern Shrine!', E'There are many shrines with incredible scenery throughout Japan. Udo Shrine in Miyazaki is famous for granting luck in love, childbirth and for its hard-to-do offerings!\n\nOn an island nation like Japan, it\'s not unusual for shrines to be built along beaches, such as at Motonosumi Inari Shrine in Yamaguchi prefecture.\n\nToday, let\'s visit Miyazaki prefecture where you will find Udo-jingū, or Udo Shrine, with its superb scenic views and original customs.\n\nIt takes approximately 10 minutes to reach the last staircase from the parking lot on the cliff above. From this vantage point one can enjoy a stunning view of the ocean scenery.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/01/26-121577.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/26-121580.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/26-121587.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/26-121583.webp"]'::jsonb, E'2016-08-08'::timestamptz, E'Miyazaki'),
(E'https://matcha-jp.com/en/15003', E'en', 45, E'Miyazaki\'s Nobeoka City: Sightseeing, Great Food, and Nature Near Takachiho Gorge', E'Nobeoka City in northern Miyazaki Prefecture is a great place to visit alongside the Takachiho Gorge. This article features access information, sightseeing spots, gourmet food, and events in Nobeoka―a city known for its natural scenery and traditional performing arts.\n\nNobeoka City is located in Kyushu\'s Miyazaki Prefecture. The city faces the ocean in the east and is surrounded by mountains. It boasts magnificent natural scenery and a rich history. It takes about 80 minutes to reach Nobeoka City by car within the prefecture.\n\nNobeoka offers various hands-on nature experiences related to the mountains, sea, and river. It\'s also where the original local cuisine called "Chicken Nanban" (deep-fried marinated chicken filets with tartare sauce) originated.\n\nNobeoka is situated close to the famous Takachiho Gorge. Since this spot is only an 80-minute bus ride from Nobeoka Station, Nobeoka is also the perfect spot to tour this gorge.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/10/24-150051.webp","https://resources.matcha-jp.com/resize/720x2000/2023/10/24-150052.webp","https://resources.matcha-jp.com/resize/720x2000/2023/11/15-152411.webp","https://resources.matcha-jp.com/resize/720x2000/2023/11/07-151236.webp"]'::jsonb, E'2023-12-05'::timestamptz, E'Takachiho Gorge'),
(E'https://matcha-jp.com/en/25448', E'en', 45, E'Where to Visit in Japan Next: Discover Miyazaki’s Natural & Culinary Treasures', E'Discover Miyazaki, Japan’s gem on Kyushu’s coast. Home to breathtaking gorges, shrines, and immersive experiences, it’s the perfect off-the-beaten-path destination for travelers seeking nature.\n\nYou\'ve explored Tokyo’s glittering skyline, wandered Kyoto’s historic lanes, and savored Osaka’s vibrant food scene. But where should you visit in Japan next? If you’re seeking something quieter, deeper, and more authentic, Miyazaki Prefecture is the perfect off-the-beaten-path destination.\n\nMiyazaki is a stunning coastal prefecture in southeastern Kyushu that remains one of Japan’s best-kept travel secrets. Here, pristine nature meets legendary mythology, award-winning wagyu, and warm hospitality, without the crowds.\n\nThis article introduces you to Miyazaki’s must-see sights, flavors, and experiences across three main themes: nature, gourmet, and culture. Whether you’re a seasoned Japan traveler or planning your next off-the-beaten-path escape, Miyazaki is the perfect destination to rediscover what made you fall in love with Japan in the first place.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/08/29-242814.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/29-242815.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/29-242816.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/29-242817.webp"]'::jsonb, E'2025-07-23'::timestamptz, E'Miyazaki'),
(E'https://matcha-jp.com/en/3829', E'en', 46, E'10 Must-See Nature Spots In Yakushima, The Ancient Cedar Island', E'Yakushima is a popular tourist spot and also a Word Heritage site located in Kagoshima. Find out more about recommended spots in the lush forests or fun treks that are must-go when visiting this island.\n\nYakushima is a World Heritage Site located in Kagoshima prefecture and a popular tourist spot. The island is rich in nature and can be enjoyed in numerous ways, such as trekking or relaxing on the bay. Today let\'s take a look at 10 of the top sightseeing spots in Yakushima.\n\nEach spot can be found on the map at the end of this article.\n\nYakusugi Land is a nature park where visitors can casually enjoy seeing the famous Yakusugi, or cedar trees. Here you can see the Yaku cedars while venturing through a massive 270 ha wide forest that stands 1,000-1,300 meters above sea level. They have refurbished wooden trails and stairs set along the way so you do not need professional trekking equipment to enjoy hiking through the forest.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/02/07-17940.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/07-17941.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/07-17942.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/07-17960.webp"]'::jsonb, E'2017-05-18'::timestamptz, E'Yakushima'),
(E'https://matcha-jp.com/en/24865', E'en', 46, E'Kagoshima Prefecture: Six Spots to Enjoy Sightseeing and Shopping', E'Kagoshima boasts a number of famous sightseeing spots, including an onsen resort and a shopping arcade. Sports Depo Frespo Jungle Park and GOLF5 Kagoshima Yojiro Shop, both frequented by the locals, are also included in that group. This article is about the appeals of those places.\n\nSakurajima, the symbol of Kagoshima/Photo by Pixta\n\nWhen asked about Kagoshima, many people will think of the grand Sakurajima. But the prefecture has many appeals besides the volcano.\n\nMany visitors from all over the world are fascinated by the prefecture\'s natural resources, unique history, and fine food.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/05/08-232922.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/08-232888.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/15-233503.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/15-233504.webp"]'::jsonb, E'2025-06-12'::timestamptz, E'Sakurajima'),
(E'https://matcha-jp.com/en/24933', E'en', 46, E'Sakurajima Travel: Best Season, Volcanic Eruptions, and Access', E'Sakurajima is an active volcanic island in Kagoshima. We introduce the scenic spots of Sakurajima, the best seasons to visit, real-time eruption information, and important tips to know before your trip (including flights and ferries).\n\nDespite being an active volcano that erupts approximately 200 times a year on average, around 4,000 people live in this area. Its dynamic scenery allows you to truly feel the power of nature. The constantly changing mountain surface, rising white smoke, and the contrast with Kagoshima Bay create a breathtaking view.\n\nIn this article, we will introduce scenic places and the best season for visiting Sakurajima, as well as how volcanic eruptions impact travel, and details about the Sakurajima live camera that lets you check the volcano\'s current state in real time.\n\nImportant: Due to continuous eruptions at Sakurajima after May 15, 2025, many flights to and from Kagoshima Airport have been canceled. For the latest flight information, please check the official websites of each airline, and for Sakurajima sightseeing information, we recommend visiting the official Sakurajima Travel website. (As of May 22, 2025)', E'["https://resources.matcha-jp.com/resize/720x2000/2025/05/22-234253.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/22-234254.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/22-234255.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/22-234256.webp"]'::jsonb, E'2025-05-22'::timestamptz, E'Sakurajima'),
(E'https://matcha-jp.com/en/11504', E'en', 47, E'Okinawa Travel: 30 Attractions, Island Activities, and Tips', E'Discover 30 top places to visit in Okinawa, with things to do, activities, hotels, shopping, and essential travel tips for first-time visitors.\n\nOkinawa Prefecture has a population of 1.47 million people spread across 160 islands (47 inhabited and 113 uninhabited).\n\nNaha Airport, located on the main island, is the prefecture\'s primary aviation hub, complemented by 12 local airports scattered throughout the region.\n\nBelow, we introduce the top 30 places to visit in Okinawa, along with the latest travel information, access tips, island activities, and local souvenir spots.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/06/05-55738.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/07-55846.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/09-132781.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/09-132786.webp"]'::jsonb, E'2023-02-13'::timestamptz, E'Okinawa'),
(E'https://matcha-jp.com/en/6201', E'en', 47, E'Miyakojima: 7 Activities on Okinawa\'s Most Beautiful Island', E'Plan your trip to Miyakojima, Okinawa’s southern paradise. Discover the best things to do, from pristine sandy beaches and water sports to local cuisine.\n\nMiyakojima, or Miyako Island, is located approximately 300 kilometers southwest of the main island of Okinawa, about a one-hour flight away.\n\nIt is connected to four islands (Ikemajima, Kurumajima, Irabujima, and Shimojijima) by bridges, and along with Taramajima and Ohgamijima, belongs to the Miyako Islands.\n\nSince no rivers run into the ocean on this flat island, the surrounding waters are very clear, boasting the highest transparency in Okinawa Prefecture, and divers from all over the world come to Miyakojima.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/06/12-56129.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/12-56130.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/12-56132.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/12-56131.webp"]'::jsonb, E'2018-07-04'::timestamptz, E'Miyako Islands'),
(E'https://matcha-jp.com/en/6190', E'en', 47, E'Naha Travel: 10 Places to Visit in Okinawa\'s Major Urban Hub', E'Discover the best of Naha, Okinawa! From top restaurants to hidden gems, here are 10 must-see sightseeing spots and activities for an unforgettable trip.\n\nThe Kenchomae Station area in Naha. Photo by Pixta\n\nNaha, home to Naha Airport—the gateway to Okinawa—is a city that beautifully blends modern urban life with retro, old-world charm.\n\nPopular destinations include the Shuri district, where the rich history of the Ryukyu Kingdom era (*1) still lingers; Kokusai Dori, a bustling street popular with international tourists; and the sleek, redeveloped area known as Naha Shintoshin.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/06/03-265102.webp","https://resources.matcha-jp.com/resize/720x2000/2026/06/03-265104.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/07-55836.webp","https://resources.matcha-jp.com/resize/720x2000/2026/06/03-265108.webp"]'::jsonb, E'2018-07-18'::timestamptz, E'Okinawa')
